from pycompss.api.task import task
from pycompss.api.api import compss_wait_on


@task(returns=bool)
def task_contains(value, target):
    """Return True if value equals target (PyCOMPSs task)."""
    return value == target

@task(returns=bool)
def combine_results(result1, result2):
    """Combine two boolean results using logical OR (PyCOMPSs task)."""
    return result1 or result2

def main(x, target):
    """
    Check if the list x contains the target value.
    Use PyCOMPSs to compute in parallel.

    Example:

    input: x=[1, 8, 2, 6, 4, 6], target=3
    output: false

    input: x=[1, 8, 2, 6, 4, 6], target=8
    output: true
    """
    result = [task_contains(value, target) for value in x]

    while len(result) > 1:
        for i in range(0, len(result), 2):
            if i + 1 < len(result):
                result[i // 2] = combine_results(result[i], result[i + 1])
            else:
                result[i // 2] = result[i]  
        result = result[: (len(result) + 1) // 2]

    result = compss_wait_on(result)
    return result[0]
